package dev.eugheist.ttmodern;
import net.minecraft.core.Direction;
import net.minecraft.world.phys.Vec3;
/** Independent initial trajectory goldens generated by audit-original-shadowbeam.py. */
final class ShadowbeamPathAudit {
 private static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT shadowbeam path: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){
  try(var stream=ShadowbeamPathAudit.class.getResourceAsStream("/assets/ttmodern/audit/shadowbeam-start.tsv")){
   if(stream==null)throw new IllegalStateException("missing original trajectory goldens");
   var lines=new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).lines().toList();
   check(lines.size()==7,"seven original yaw/pitch fixtures");
   for(var line:lines){var c=line.split("\\s+");var start=ShadowbeamPath.start(12.25,64,-7.75,1.62f,Float.parseFloat(c[0]),Float.parseFloat(c[1]));var actual=new double[]{start.position().x,start.position().y,start.position().z,start.velocity().x,start.velocity().y,start.velocity().z};for(int i=0;i<6;i++)check(Math.abs(actual[i]-Double.parseDouble(c[i+2]))<1e-12,"original start yaw="+c[0]+" pitch="+c[1]+" component="+i+" actual="+actual[i]);}
  }catch(java.io.IOException e){throw new IllegalStateException(e);}
  var v=new Vec3(.031,-.077,.129);
  for(var side:Direction.values()){
   var reflected=ShadowbeamPath.reflect(v,side);
   check(Math.abs(reflected.lengthSqr()-v.lengthSqr())<1e-15,"reflection conserves speed "+side);
   check(ShadowbeamPath.reflect(reflected,side).distanceToSqr(v)<1e-30,"two reflections restore direction "+side);
   var normal=new Vec3(side.getStepX(),side.getStepY(),side.getStepZ());
   check(Math.abs(reflected.dot(normal)+v.dot(normal))<1e-15,"normal component changes sign "+side);
  }
  var box=new net.minecraft.world.phys.AABB(0,0,0,1,1,1);
  check(ShadowbeamPath.intercept(box,new Vec3(-1,.5,.5),new Vec3(2,.5,.5)).orElseThrow().equals(new Vec3(0,.5,.5)),"outside nearest entry");
  check(ShadowbeamPath.intercept(box,new Vec3(.5,.5,.5),new Vec3(2,.5,.5)).orElseThrow().equals(new Vec3(1,.5,.5)),"inside uses exit plane unlike modern clip");
  check(ShadowbeamPath.intercept(box,new Vec3(.5,.5,.5),new Vec3(.6,.5,.5)).isEmpty(),"entirely inside is not an intersection");
  check(ShadowbeamPath.intercept(box,new Vec3(-.0001,.5,.5),new Vec3(.0001,.5,.5)).isEmpty(),"original squared float parallel threshold");
  check(ShadowbeamPath.intercept(box,new Vec3(-1,1,.5),new Vec3(0,1,.5)).orElseThrow().equals(new Vec3(0,1,.5)),"inclusive face edge and segment endpoint");
  check(ShadowbeamPath.intercept(box,new Vec3(-1,1.00001,.5),new Vec3(2,1.00001,.5)).isEmpty(),"outside face bounds refuses");
  check(ShadowbeamPath.STEPS==300&&java.util.stream.IntStream.range(0,ShadowbeamPath.STEPS).filter(ShadowbeamPath::sparkle).count()==297,"synchronous original lifetime300/sparkles297");
  var level=server.overworld();var wall=new net.minecraft.core.BlockPos(5,290,6);var old=level.getBlockState(wall);
  var shooter=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"ShadowbeamAudit"));shooter.setPos(5,290,0);
  try{
   level.setBlockAndUpdate(wall,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());
   var result=ShadowbeamTrace.run(level,shooter,new ShadowbeamPath.Start(new Vec3(5.5,290.5,5),new Vec3(0,0,.15)));
   check(result.blockHits()==1&&result.entityHits()==0,"one native stone collision, no entity");
   check(Math.abs(result.position().z-(-38.2))<1e-10&&result.velocity().equals(new Vec3(0,0,-.15)),"reflect before advancing from old position and preserve speed over300 steps");
   check(level.getBlockState(wall).is(net.minecraft.world.level.block.Blocks.STONE),"collision leaves wall intact");
  }finally{level.setBlockAndUpdate(wall,old);}
  var target=net.minecraft.world.entity.EntityType.COW.create(level);target.setPos(5.5,290,7);target.setNoAi(true);target.setNoGravity(true);level.addFreshEntity(target);
  try{
   level.setBlockAndUpdate(wall,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());
   var start=new ShadowbeamPath.Start(new Vec3(5.5,290.5,5),new Vec3(0,0,.15));
   var blocked=ShadowbeamTrace.run(level,shooter,start);
   check(blocked.entityHits()==0&&target.getHealth()==10,"wall truncates entity ray and prevents damage behind it");
   level.setBlockAndUpdate(wall,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());
   var hit=ShadowbeamTrace.run(level,shooter,start);
   check(hit.entityHits()>0&&target.getHealth()==2,"native player damage8, remaining synchronous hits respect hurt immunity: hits="+hit.entityHits()+" health="+target.getHealth());
   check(Math.abs(hit.position().z-50)<1e-10&&hit.velocity().equals(start.velocity()),"entity impact neither stops nor reflects beam");
  }finally{target.discard();level.setBlockAndUpdate(wall,old);}
  var victim=new RecordingPlayer(level);victim.setPos(5.5,290,7);level.addNewPlayer(victim);
  boolean oldPvp=server.isPvpAllowed();
  try{
   var start=new ShadowbeamPath.Start(new Vec3(5.5,290.5,5),new Vec3(0,0,.15));
   server.setPvpAllowed(false);var denied=ShadowbeamTrace.run(level,shooter,start);
   check(denied.entityHits()>0&&victim.attempts==0,"native entity query sees player but disabled PvP prevents damage dispatch");
   server.setPvpAllowed(true);ShadowbeamTrace.run(level,shooter,start);
   check(victim.attempts>0&&victim.amount==8&&victim.attacker==shooter,"enabled PvP dispatches original8 player-attributed damage");
   victim.attempts=0;
   var ownerHit=ShadowbeamTrace.run(level,victim,new ShadowbeamPath.Start(new Vec3(5.5,290.5,5),new Vec3(0,0,.15)));
   check(ownerHit.entityHits()>0&&victim.attempts==0,"owner can obstruct after first four updates but never receives own damage");
  }finally{server.setPvpAllowed(oldPvp);level.removePlayerImmediately(victim,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);}
  var focus=ShadowbeamFocus.ITEM.get();var focusStack=new net.minecraft.world.item.ItemStack(focus);
  check(focusStack.getRarity()==net.minecraft.world.item.Rarity.EPIC&&focus.isVisCostPerTick(focusStack)&&focus.getFocusColor(focusStack)==4915283&&focus.getPossibleUpgradesByRank(focusStack,1).length==0,"original focus rarity,color,per-tick and no upgrades");
  var wand=new net.minecraft.world.item.ItemStack(dev.eugheist.tc4modern.TC4Modern.GOLD_GREATWOOD_WAND.get());
  dev.eugheist.tc4modern.FociContent.setFocus(wand,focusStack);
  for(var aspect:thaumcraft.api.aspects.Aspect.getPrimalAspects())dev.eugheist.tc4modern.WandData.add(wand,aspect,10,true);
  int order=dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.ORDER),entropy=dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.ENTROPY),air=dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.AIR);
  focus.onUsingFocusTick(wand,shooter,100);
  check(order-dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.ORDER)==25&&entropy-dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.ENTROPY)==25&&air-dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.AIR)==15,"original per-tick centivis costs25/25/15");
  var empty=new net.minecraft.world.item.ItemStack(dev.eugheist.tc4modern.TC4Modern.GOLD_GREATWOOD_WAND.get());var before=empty.copy();focus.onUsingFocusTick(empty,shooter,99);check(net.minecraft.world.item.ItemStack.matches(empty,before),"insufficient vis leaves wand unchanged");
  var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("FOCUS_SHADOWBEAM")).findFirst().orElseThrow();
  check(recipe.componentStacks().size()==6&&recipe.componentStacks().get(1).is(net.minecraft.world.item.Items.ARROW)&&recipe.componentStacks().get(3).is(dev.eugheist.tc4modern.FociWorld.EXCAVATION.get())&&recipe.componentStacks().get(4).is(ThaumicTinkererModern.FOCUS_DEFLECT.get()),"original six infusion components");
  System.out.println("TT SHADOWBEAM PATH AUDIT: ALL PASS (original runtime goldens seven angles,position and velocity,float precision,six reflection normals,speed conservation,legacy box entry/exit/inside/parallel/edge,native wall bounce and conservation,blocked target/native8damage/piercing,PvP dispatch and owner exclusion,focus cost/rarity/recipe,300 steps/297 sparkles)");
 }
 private static final class RecordingPlayer extends net.neoforged.neoforge.common.util.FakePlayer {
  int attempts;float amount;net.minecraft.world.entity.Entity attacker;
  RecordingPlayer(net.minecraft.server.level.ServerLevel level){super(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"ShadowbeamVictim"));}
  @Override public boolean hurt(net.minecraft.world.damagesource.DamageSource source,float damage){attempts++;amount=damage;attacker=source.getEntity();return false;}
 }

}
